CREATE TABLE IF NOT EXISTS billing_token_daily_versions (job_id VARCHAR(40) NOT NULL,instance_id VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,token_id BIGINT NOT NULL DEFAULT 0,token_name VARCHAR(128) NOT NULL DEFAULT '',username VARCHAR(128) DEFAULT '',model_name VARCHAR(255) NOT NULL,group_name VARCHAR(64) DEFAULT '',tier_from BIGINT NOT NULL DEFAULT 0,day DATE NOT NULL,request_count BIGINT NOT NULL DEFAULT 0,prompt_tokens BIGINT NOT NULL DEFAULT 0,completion_tokens BIGINT NOT NULL DEFAULT 0,cache_tokens BIGINT NOT NULL DEFAULT 0,cache_write_tokens BIGINT NOT NULL DEFAULT 0,cache_write_5m_tokens BIGINT NOT NULL DEFAULT 0,cache_write_1h_tokens BIGINT NOT NULL DEFAULT 0,quota BIGINT NOT NULL DEFAULT 0,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(job_id,user_id,token_id,model_name,group_name,tier_from,day),KEY idx_token_versions_report(instance_id,day,user_id,token_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
